def transform(grid):
    out = [row[:] for row in grid]
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    h, w = len(grid), len(grid[0])
    # Find two vertically separated copies of the same foreground motif. Treat
    # the upper copy as the reference; mark background cells missing from the
    # lower copy where the reference has foreground.
    active = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    groups = []
    for r in active:
        if not groups or r != groups[-1][-1] + 1:
            groups.append([r])
        else:
            groups[-1].append(r)
    if len(groups) >= 2:
        upper, lower = groups[0], groups[1]
        n = min(len(upper), len(lower))
        # Align the same-length motifs row by row.
        for k in range(n):
            a, b = upper[k], lower[k]
            for c in range(w):
                if grid[a][c] != bg and grid[b][c] == bg:
                    out[b][c] = 1
    return out

